 "content": "from collections import Counter, deque


def transform(grid):
    """Replace isolated stray cells by the local 4-neighbor region color."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            components.append((color, comp))

    # Only singleton components are noise; preserve all connected shapes.
    changes = []
    for color, comp in components:
        if len(comp) != 1:
            continue
        r, c = comp[0]
        neighbors = [grid[y][x] for y, x in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))
                     if 0 <= y < h and 0 <= x < w]
        if not neighbors:
            continue
        counts = Counter(neighbors)
        best_count = max(counts.values())
        winners = [v for v, n in counts.items() if n == best_count]
        if len(winners) == 1 and best_count > len(neighbors) / 2:
            changes.append((r, c, winners[0]))
        elif len(winners) == 1:
            changes.append((r, c, winners[0]))
        else:
            # Resolve ties toward the globally most common color.
            global_counts = Counter(v for row in grid for v in row)
            bg = global_counts.most_common(1)[0][0]
            changes.append((r, c, bg))
    for r, c, color in changes:
        out[r][c] = color
    return out
